using System;using System.IO;using System.Linq;using Newtonsoft.Json.Linq;using SpatialWallpaper.Sdk.Hosting;using SpatialWallpaper.Sdk.Editor;
static class PreviewCacheChecks {
 static void Need(bool yes,string reason){if(!yes)throw new Exception(reason);}
 static void Refused(Action action,string reason){bool refused=false;try{action();}catch(InvalidOperationException){refused=true;}catch(InvalidDataException){refused=true;}Need(refused,reason);}
 static string Launch(string data,JObject status,int age){string launch=Path.Combine(data,"launches",Guid.NewGuid().ToString("N")),native=Path.Combine(launch,"native");Directory.CreateDirectory(native);File.WriteAllText(Path.Combine(launch,"preview.json"),"{}");File.WriteAllText(Path.Combine(native,"status.json"),status.ToString());File.WriteAllText(Path.Combine(native,"stop-request"),"stop");SandboxPreviewCache.Completed(native);Directory.SetLastWriteTimeUtc(launch,new DateTime(2020,1,1).AddMinutes(age));return launch;}
 static int Main(string[] args){try{string output=args[0];var status=JObject.Parse(File.ReadAllText(args[1]));
  string data=Path.Combine(output,"bounded");for(int i=0;i<20;i++)Launch(data,status,i);SandboxPreviewCache.TrimLaunches(data);Need(Directory.GetDirectories(Path.Combine(data,"launches")).Length==16,"completed-launch-cache-not-bounded");
  string foreignData=Path.Combine(output,"preserve-unknown");for(int i=0;i<16;i++)Launch(foreignData,status,i+1);string candidate=Launch(foreignData,status,0),sentinel=Path.Combine(candidate,"native/user-file.txt");File.WriteAllText(sentinel,"owned test sentinel");Refused(()=>SandboxPreviewCache.TrimLaunches(foreignData),"cache-deleted-unknown-file");Need(File.ReadAllText(sentinel)=="owned test sentinel","cache-changed-unknown-file");
  using(var self=PinnedProcessOwner.PinCurrent()){var live=(JObject)status.DeepClone();live["viewer_pid"]=self.Id;live["viewer_creation_filetime"]=self.CreationFileTime;string liveData=Path.Combine(output,"preserve-live");for(int i=0;i<16;i++)Launch(liveData,status,i+1);string held=Launch(liveData,live,0);Refused(()=>SandboxPreviewCache.TrimLaunches(liveData),"cache-trusted-final-file-over-live-kernel");Need(Directory.Exists(held),"cache-deleted-live-owner");}
  string snapshotData=Path.Combine(output,"snapshots"),directory=Path.Combine(snapshotData,"snapshots",Guid.NewGuid().ToString("N")),path=Path.Combine(directory,"scene.spatial");Directory.CreateDirectory(directory);File.WriteAllText(path,"owned snapshot");string outside=Path.Combine(output,"outside.spatial");File.WriteAllText(outside,"preserve");Refused(()=>SandboxPreviewCache.RemoveSnapshot(snapshotData,outside),"snapshot-cache-escaped-root");Need(File.ReadAllText(outside)=="preserve","snapshot-cache-changed-outside");
  string extra=Path.Combine(directory,"author-file.txt");File.WriteAllText(extra,"preserve");Refused(()=>SandboxPreviewCache.RemoveSnapshot(snapshotData,path),"snapshot-cache-deleted-unknown-entry");Need(File.Exists(path)&&File.Exists(extra),"snapshot-cache-changed-unknown-directory");File.Delete(extra);SandboxPreviewCache.RemoveSnapshot(snapshotData,path);Need(!Directory.Exists(directory),"retired-snapshot-not-removed");
  File.WriteAllText(Path.Combine(output,"result.json"),new JObject{{"completed_retained",16},{"foreign_files_preserved",true},{"live_kernel_beats_final_status_file",true},{"snapshot_boundary_preserved",true},{"retired_snapshot_removed",true}}.ToString());Console.WriteLine("PASS bounded-cache-and-preservation-controls");return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
